import fs from "node:fs";
import { createRequire } from "node:module";

const require = createRequire("/home/agentops/dev/vea_validators/vea/package.json");
const yaml = require("js-yaml");

const p = "/home/agentops/dev/vea_validators/vea/.github/workflows/dependency-review.yml";
const raw = fs.readFileSync(p, "utf8");

if (raw.includes("\t")) {
  console.log("FAIL: tab character present");
  process.exit(1);
}
console.log("no tab characters: OK");

const doc = yaml.load(raw);
console.log("YAML parsed OK");

const job = doc.jobs["dependency-review"];
console.log("job env:", JSON.stringify(job.env, null, 2));
console.log("steps:", JSON.stringify(job.steps.map((s) => s.name)));

const dr = job.steps.find((s) => s.name === "Dependency Review");
console.log("dependency-review uses:", dr.uses);
console.log("allow-ghsas:", JSON.stringify(dr.with["allow-ghsas"]));

const hr = job.steps.find((s) => s.name === "Harden Runner");
console.log("harden-runner uses:", hr.uses);
const co = job.steps.find((s) => s.name === "Checkout Repository");
console.log("checkout uses:", co.uses);

const guard = job.steps.find((s) => s.name === "Validate GHSA exception scope");
console.log("guard shell:", guard.shell);
console.log("guard run line count:", guard.run.split("\n").length);
fs.writeFileSync("/tmp/guard.sh", guard.run);
console.log("guard script written to /tmp/guard.sh");

